#!/usr/bin/env node
'use strict';

/*
 * Compare the DOI-to-DOI citation plan generated by build.js with the public
 * Zenodo record state. This command is deliberately read-only: provider
 * acceptance is an external event and must not be inferred from local data.
 *
 * Usage:
 *   node build.js
 *   node tools/audit-reference-discoverability.js
 *   node tools/audit-reference-discoverability.js --json
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const DIST = path.join(ROOT, 'dist', 'api');
const JSON_OUTPUT = process.argv.includes('--json');

function read(name) {
  const file = path.join(DIST, name);
  if (!fs.existsSync(file)) throw new Error(`missing ${file}; run node build.js first`);
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function zenodoId(url) {
  const raw = String(url || '');
  const recordMatch = raw.match(/^https:\/\/zenodo\.org\/(?:record|records)\/(\d+)\/?$/);
  if (recordMatch) return recordMatch[1];
  const doiMatch = raw.match(/^https:\/\/doi\.org\/10\.5281\/zenodo\.(\d+)\/?$/);
  return doiMatch ? doiMatch[1] : null;
}

function normalizedDoi(value) {
  return String(value || '').replace(/^https:\/\/doi\.org\//i, '').trim().toLowerCase();
}

async function fetchRecord(id) {
  const response = await fetch(`https://zenodo.org/api/records/${id}`, {
    headers: { accept: 'application/json', 'user-agent': 'Evidence-Press-reference-audit/1.0' }
  });
  if (!response.ok) throw new Error(`Zenodo record ${id}: HTTP ${response.status}`);
  return response.json();
}

async function mapLimit(items, limit, fn) {
  const output = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      const index = next++;
      output[index] = await fn(items[index], index);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return output;
}

async function main() {
  const papers = read('papers.json').papers;
  const citations = read('citations.json').citations;
  const plannedByDoi = new Map();
  for (const citation of citations) {
    const key = normalizedDoi(citation.citingDoi);
    if (!plannedByDoi.has(key)) plannedByDoi.set(key, new Map());
    plannedByDoi.get(key).set(normalizedDoi(citation.citedDoi), citation);
  }

  const records = await mapLimit(papers, 4, async paper => {
    const recordId = zenodoId(paper.zenodoUrl);
    if (!recordId) return { releaseSlug: paper.slug, releaseDoi: paper.doi, error: 'unparseable Zenodo record URL' };
    const provider = await fetchRecord(recordId);
    const existingRelated = (provider.metadata && provider.metadata.related_identifiers) || [];
    const existingCites = new Set(existingRelated
      .filter(item => String(item.relation || '').toLowerCase() === 'cites' && String(item.scheme || '').toLowerCase() === 'doi')
      .map(item => normalizedDoi(item.identifier)));
    const planned = [...(plannedByDoi.get(normalizedDoi(paper.doi)) || new Map()).values()];
    const missing = planned.filter(item => !existingCites.has(normalizedDoi(item.citedDoi)));
    const unplannedExisting = [...existingCites]
      .filter(doi => !planned.some(item => normalizedDoi(item.citedDoi) === doi));
    return {
      releaseSlug: paper.slug,
      releaseDoi: paper.doi,
      zenodoRecordId: Number(recordId),
      providerStatus: provider.status,
      providerUpdated: provider.updated || null,
      plannedCitesCount: planned.length,
      existingCitesCount: existingCites.size,
      missingCitesCount: missing.length,
      missingCites: missing.map(item => ({ citedDoi: item.citedDoi, citation: item.citation })),
      unplannedExistingCites: unplannedExisting,
      referencesFieldPresent: Array.isArray(provider.metadata && provider.metadata.references),
      existingNonCitationRelations: existingRelated.filter(item => String(item.relation || '').toLowerCase() !== 'cites')
    };
  });

  const report = {
    schemaVersion: '1.0',
    auditType: 'read-only-public-provider-comparison',
    provider: 'https://zenodo.org',
    generatedAt: new Date().toISOString(),
    claimBoundary: 'Missing means absent from the public Zenodo record at retrieval time. Planned means derived from canonical DOI or arXiv URLs in Evidence Press source metadata. No metadata was changed.',
    summary: {
      releaseCount: records.length,
      plannedCitationCount: citations.length,
      existingCitationCount: records.reduce((sum, record) => sum + (record.existingCitesCount || 0), 0),
      missingCitationCount: records.reduce((sum, record) => sum + (record.missingCitesCount || 0), 0),
      recordsWithoutReferencesField: records.filter(record => record.referencesFieldPresent === false).length,
      errorCount: records.filter(record => record.error).length
    },
    records
  };

  if (JSON_OUTPUT) process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  else {
    console.log(`Zenodo citation audit: ${report.summary.releaseCount} records`);
    console.log(`  planned DOI citations: ${report.summary.plannedCitationCount}`);
    console.log(`  currently registered cites relations: ${report.summary.existingCitationCount}`);
    console.log(`  missing cites relations: ${report.summary.missingCitationCount}`);
    console.log(`  records without references metadata: ${report.summary.recordsWithoutReferencesField}`);
    console.log(`  provider/read errors: ${report.summary.errorCount}`);
    for (const record of records.filter(item => item.error || item.missingCitesCount))
      console.log(`  ${record.releaseSlug}: ${record.error || `${record.missingCitesCount} missing of ${record.plannedCitesCount} planned`}`);
  }
}

main().catch(error => {
  console.error(error.stack || error.message);
  process.exit(1);
});
